from pathlib import Path
import re

path = Path('vision-sync.js')
text = path.read_text('utf-8')
text = text.replace("const CONTRACT='ANCHOR_FREE_STRUCTURAL_V3';", "const CONTRACT='ANCHOR_FREE_STRUCTURAL_V4';")
text = text.replace("topologyScore:0,denseScore:0,angle:0", "topologyScore:0,denseScore:0,contourScore:0,phaseScore:0,angle:0")
text = text.replace(" · dense ${state.denseScore.toFixed(3)} · verify ${state.verifyScore.toFixed(3)}", " · contour ${state.contourScore.toFixed(3)} · phase ${state.phaseScore.toFixed(3)} · verify ${state.verifyScore.toFixed(3)}")

# Preserve the normalized signed local high-pass field. This is structural detail, not raw photometric color.
text = text.replace("edge=new Float32Array(w*h),ridge=new Float32Array(w*h)", "high=new Float32Array(w*h),edge=new Float32Array(w*h),ridge=new Float32Array(w*h)")
text = text.replace("local=Math.abs(gray[i]-coarse[i]);edge[i]=e;", "high[i]=gray[i]-coarse[i];const local=Math.abs(high[i]);edge[i]=e;")
text = text.replace("return{w,h,gray,edge,ridge,flat,coast,cos2,sin2,edgeP,ridgeP,contrast:range/255}", "return{w,h,gray,high,edge,ridge,flat,coast,cos2,sin2,edgeP,ridgeP,contrast:range/255}")

extra = r'''function fieldStrength(f,x,y){x=Math.round(x);y=Math.round(y);if(x<1||y<1||x>=f.w-1||y>=f.h-1)return 0;let best=0;for(let yy=y-1;yy<=y+1;yy++)for(let xx=x-1;xx<=x+1;xx++){const i=yy*f.w+xx,e=clamp(f.edge[i]/f.edgeP,0,1),r=clamp(f.ridge[i]/f.ridgeP,0,1),c=f.coast[i];best=Math.max(best,.50*e+.30*r+.20*c)}return best}
function bidirectionalContourScore(source,field,cx,cy,radius,angle){if(!source||!field||radius<=0)return{score:-1,recall:0,precision:0,orientation:0};const mx=(source.w-1)/2,my=(source.h-1)/2,a=rad(angle),c=Math.cos(a),s=Math.sin(a),ca=Math.cos(2*a),sa=Math.sin(2*a);let rec=0,recW=0,ori=0,oriW=0;for(let sy=5;sy<source.h-5;sy+=2)for(let sx=5;sx<source.w-5;sx+=2){const nx=(sx-mx)/(source.w/2),ny=(sy-my)/(source.h/2),ring=Math.hypot(nx,ny);if(ring<.18||ring>.80)continue;const si=sy*source.w+sx,se=clamp(source.edge[si]/source.edgeP,0,1),sr=clamp(source.ridge[si]/source.ridgeP,0,1),sc=source.coast[si],ss=.50*se+.30*sr+.20*sc;if(ss<.28)continue;const tx=cx+(nx*c-ny*s)*radius,ty=cy+(nx*s+ny*c)*radius,ts=fieldStrength(field,tx,ty),w=.25+.75*ss;rec+=w*ts;recW+=w;const ix=Math.round(tx),iy=Math.round(ty);if(ix>1&&iy>1&&ix<field.w-1&&iy<field.h-1&&ts>.25){const ti=iy*field.w+ix,rc2=source.cos2[si]*ca-source.sin2[si]*sa,rs2=source.sin2[si]*ca+source.cos2[si]*sa,align=.5+.5*(field.cos2[ti]*rc2+field.sin2[ti]*rs2);ori+=w*align;oriW+=w}}let prec=0,precW=0;const box=Math.ceil(radius*.84),step=radius>45?3:2;for(let ty=Math.floor(cy-box);ty<=Math.ceil(cy+box);ty+=step)for(let tx=Math.floor(cx-box);tx<=Math.ceil(cx+box);tx+=step){if(tx<2||ty<2||tx>=field.w-2||ty>=field.h-2)continue;const dx=(tx-cx)/radius,dy=(ty-cy)/radius,nx=dx*c+dy*s,ny=-dx*s+dy*c,ring=Math.hypot(nx,ny);if(ring<.18||ring>.80)continue;const ti=ty*field.w+tx,te=clamp(field.edge[ti]/field.edgeP,0,1),tr=clamp(field.ridge[ti]/field.ridgeP,0,1),tc=field.coast[ti],ts=.50*te+.30*tr+.20*tc;if(ts<.28)continue;const sx=mx+nx*(source.w/2),sy=my+ny*(source.h/2),ss=fieldStrength(source,sx,sy),w=.25+.75*ts;prec+=w*ss;precW+=w}const recall=recW?rec/recW:0,precision=precW?prec/precW:0,f1=recall+precision?2*recall*precision/(recall+precision):0,orientation=oriW?ori/oriW:.5;return{score:.82*f1+.18*orientation,recall,precision,orientation}}
function bilinear(array,w,h,x,y){if(x<0||y<0||x>w-1||y>h-1)return 0;const x0=Math.floor(x),y0=Math.floor(y),x1=Math.min(w-1,x0+1),y1=Math.min(h-1,y0+1),fx=x-x0,fy=y-y0,a=array[y0*w+x0]*(1-fx)+array[y0*w+x1]*fx,b=array[y1*w+x0]*(1-fx)+array[y1*w+x1]*fx;return a*(1-fy)+b*fy}
function structuralPhaseScore(source,field,cx,cy,radius,angle){if(!source?.high||!field?.high||radius<=0)return{score:-1,ncc:-1,count:0};const mx=(source.w-1)/2,my=(source.h-1)/2,a=rad(angle),c=Math.cos(a),s=Math.sin(a);let sxSum=0,txSum=0,count=0,pairs=[];for(let sy=6;sy<source.h-6;sy+=2)for(let sx=6;sx<source.w-6;sx+=2){const nx=(sx-mx)/(source.w/2),ny=(sy-my)/(source.h/2),ring=Math.hypot(nx,ny);if(ring<.18||ring>.80)continue;const tx=cx+(nx*c-ny*s)*radius,ty=cy+(nx*s+ny*c)*radius;if(tx<2||ty<2||tx>=field.w-2||ty>=field.h-2)continue;const sv=source.high[sy*source.w+sx],tv=bilinear(field.high,field.w,field.h,tx,ty);pairs.push([sv,tv]);sxSum+=sv;txSum+=tv;count++}if(count<180)return{score:-1,ncc:-1,count};const sm=sxSum/count,tm=txSum/count;let ab=0,a2=0,b2=0;for(const [sv,tv] of pairs){const aa=sv-sm,bb=tv-tm;ab+=aa*bb;a2+=aa*aa;b2+=bb*bb}const ncc=a2>1e-7&&b2>1e-7?ab/Math.sqrt(a2*b2):-1;return{score:clamp((ncc+.12)/1.12,0,1),ncc,count}}
'''
if 'function bidirectionalContourScore(' not in text:
    text = text.replace('function denseStructuralScore(', extra + 'function denseStructuralScore(', 1)

coarse = r'''async function coarseMatch(info,cfg){const atlas=await coarseAtlas(cfg),field=atlas.field,samples=info.samples,stride=cfg.width===32768?7:4,radii=cfg.width===32768?[6,9,13,18,25,34]:[5,8,12,17,24],angles=[0,45,90,135,180,225,270,315],templates=[];for(const r of radii)for(const a of angles)templates.push({radius:r,angle:a,tpl:template(samples,r,a)});const topByRadius=new Map(radii.map(r=>[r,[]]));let bestSeen=0,rows=0;for(let y=stride;y<field.h-stride;y+=stride){for(let x=stride;x<field.w-stride;x+=stride){const target=pixelToGlobal(x*atlas.factor,y*atlas.factor,COARSE_Z,cfg);if(!inGlobalBounds(target))continue;for(const r of radii){let scaleBest=null;for(const t of templates){if(t.radius!==r)continue;const sc=scoreAt(field,x,y,t.tpl);if(sc.score<0)continue;if(!scaleBest||sc.score>scaleBest.score)scaleBest={x,y,radius:r,angle:t.angle,...sc}}if(scaleBest){pushTop(topByRadius.get(r),scaleBest,80);bestSeen=Math.max(bestSeen,scaleBest.score)}}}rows++;if(rows%5===0){state.coarseScore=bestSeen;setDiag('SEARCH',`global coarse ${Math.round(y/field.h*100)}%`,'coarse-global');await sleep(0)}}const seeds=[];for(const r of radii){const pool=topByRadius.get(r)||[];for(const item of pool.slice(0,56)){const dense=denseStructuralScore(info.field,field,item.x,item.y,item.radius,item.angle),contour=bidirectionalContourScore(info.field,field,item.x,item.y,item.radius,item.angle),phase=structuralPhaseScore(info.field,field,item.x,item.y,item.radius,item.angle);item.denseScore=dense.score;item.contourScore=contour.score;item.phaseScore=phase.score;item.rankScore=.10*item.score+.12*Math.max(0,dense.score)+.30*Math.max(0,contour.score)+.48*Math.max(0,phase.score)}pool.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));const chosen=[];for(const item of pool){if(chosen.every(seed=>Math.hypot(item.x-seed.x,item.y-seed.y)>=Math.max(12,r*.58))){chosen.push(item);seeds.push(item);if(chosen.length>=8)break}}}seeds.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));if(!seeds.length)return null;const hypotheses=[];for(const seed of seeds.slice(0,48)){const refineTop=[];for(let y=seed.y-stride*1.5;y<=seed.y+stride*1.5;y+=2)for(let x=seed.x-stride*1.5;x<=seed.x+stride*1.5;x+=2){const target=pixelToGlobal(x*atlas.factor,y*atlas.factor,COARSE_Z,cfg);if(!inGlobalBounds(target))continue;for(const rf of [.84,.90,.95,1,1.05,1.11,1.18])for(const da of [-22.5,-15,-7.5,0,7.5,15,22.5]){const radius=seed.radius*rf,angle=angleNorm(seed.angle+da),sc=scoreAt(field,x,y,template(samples,radius,angle));pushTop(refineTop,{x,y,radius,angle,...sc},36)}}for(const item of refineTop.slice(0,28)){const dense=denseStructuralScore(info.field,field,item.x,item.y,item.radius,item.angle),contour=bidirectionalContourScore(info.field,field,item.x,item.y,item.radius,item.angle),phase=structuralPhaseScore(info.field,field,item.x,item.y,item.radius,item.angle);item.denseScore=dense.score;item.contourScore=contour.score;item.phaseScore=phase.score;item.rankScore=.08*item.score+.10*Math.max(0,dense.score)+.27*Math.max(0,contour.score)+.55*Math.max(0,phase.score)}refineTop.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));hypotheses.push(refineTop[0]||seed);await sleep(0)}hypotheses.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));const best=hypotheses[0],second=hypotheses.find(x=>x!==best&&Math.hypot(x.x-best.x,x.y-best.y)>=Math.max(13,best.radius*.55)),margin=second?(best.rankScore??best.score)-(second.rankScore??second.score):(best.rankScore??best.score);return{...best,margin,atlas,hypotheses}}'''
text, n = re.subn(r'^async function coarseMatch\(info,cfg\)\{.*$', coarse, text, count=1, flags=re.M)
assert n == 1, 'coarseMatch replacement failed'

fine = r'''async function fineMatch(samples,cfg,pred,search=170,step=10,srcField=null){const atlasFactor=pred.atlas?.factor??(cfg.width===32768?4:2),scale=atlasFactor*(2**(FINE_Z-COARSE_Z)),centerX=pred.x*scale,centerY=pred.y*scale,radius=pred.radius*scale,fine=await fineFieldAround(cfg,centerX,centerY,radius,search),top=[];for(let y=fine.centerLocalY-search;y<=fine.centerLocalY+search;y+=step){for(let x=fine.centerLocalX-search;x<=fine.centerLocalX+search;x+=step)for(const rf of [.85,.91,.96,1,1.04,1.10,1.16])for(const da of [-15,-10,-5,0,5,10,15]){const rr=radius*rf,aa=angleNorm(pred.angle+da),sc=scoreAt(fine.field,x,y,template(samples,rr,aa));pushTop(top,{x,y,radius:rr,angle:aa,...sc},120)}await sleep(0)}if(!top.length)return null;for(const item of top.slice(0,60)){const dense=srcField?denseStructuralScore(srcField,fine.field,item.x,item.y,item.radius,item.angle):{score:-1},contour=srcField?bidirectionalContourScore(srcField,fine.field,item.x,item.y,item.radius,item.angle):{score:-1},phase=srcField?structuralPhaseScore(srcField,fine.field,item.x,item.y,item.radius,item.angle):{score:-1};item.denseScore=dense.score;item.contourScore=contour.score;item.phaseScore=phase.score;item.rankScore=srcField?.08*item.score+.10*Math.max(0,dense.score)+.27*Math.max(0,contour.score)+.55*Math.max(0,phase.score):item.score}top.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));let best=top[0],ref=[];for(let y=best.y-18;y<=best.y+18;y+=2)for(let x=best.x-18;x<=best.x+18;x+=2)for(const rf of [.94,.97,.99,1,1.01,1.03,1.06])for(const da of [-6,-3,-1.5,0,1.5,3,6]){const rr=best.radius*rf,aa=angleNorm(best.angle+da),sc=scoreAt(fine.field,x,y,template(samples,rr,aa));pushTop(ref,{x,y,radius:rr,angle:aa,...sc},72)}for(const item of ref.slice(0,60)){const dense=srcField?denseStructuralScore(srcField,fine.field,item.x,item.y,item.radius,item.angle):{score:-1},contour=srcField?bidirectionalContourScore(srcField,fine.field,item.x,item.y,item.radius,item.angle):{score:-1},phase=srcField?structuralPhaseScore(srcField,fine.field,item.x,item.y,item.radius,item.angle):{score:-1};item.denseScore=dense.score;item.contourScore=contour.score;item.phaseScore=phase.score;item.rankScore=srcField?.06*item.score+.08*Math.max(0,dense.score)+.26*Math.max(0,contour.score)+.60*Math.max(0,phase.score):item.score}ref.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));if(ref.length)best=ref[0];const all=(ref.length?ref:top),second=all.find(x=>x!==best&&Math.hypot(x.x-best.x,x.y-best.y)>=Math.max(22,best.radius*.12)),margin=second?(best.rankScore??best.score)-(second.rankScore??second.score):(best.rankScore??best.score),globalX=best.x+fine.minX*256,globalY=best.y+fine.minY*256;return{...best,globalX,globalY,margin,fieldGrid:fine,scaleFromCoarse:scale}}'''
text, n = re.subn(r'^async function fineMatch\(samples,cfg,pred,search=170,step=10,srcField=null\)\{.*$', fine, text, count=1, flags=re.M)
assert n == 1, 'fineMatch replacement failed'

global_match = r'''async function globalMatch(info,cfg){const coarseSearch=await coarseMatch(info,cfg);if(!coarseSearch)return{coarse:null,fine:null};state.coarseScore=coarseSearch.score;state.coarseMargin=coarseSearch.margin||0;setDiag('SEARCH','coarse candidates found; refining tiles','fine-global');const finals=[];for(const hypothesis of (coarseSearch.hypotheses||[coarseSearch]).slice(0,COARSE_BEAM)){const fine=await fineMatch(info.samples,cfg,{...hypothesis,atlas:coarseSearch.atlas},220,12,info.field);if(fine){const verify=verifyAt(fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle,info.verifySamples),dense=Number.isFinite(fine.denseScore)?fine.denseScore:denseStructuralScore(info.field,fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle).score,contour=Number.isFinite(fine.contourScore)?fine.contourScore:bidirectionalContourScore(info.field,fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle).score,phase=Number.isFinite(fine.phaseScore)?fine.phaseScore:structuralPhaseScore(info.field,fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle).score,combined=.08*fine.score+.08*Math.max(0,dense)+.24*Math.max(0,contour)+.48*Math.max(0,phase)+.12*verify.score;finals.push({fine:{...fine,denseScore:dense,contourScore:contour,phaseScore:phase},hypothesis,verify,combined})}await sleep(0)}if(!finals.length)return{coarse:coarseSearch,fine:null};finals.sort((a,b)=>b.combined-a.combined);const winner=finals[0],second=finals.find(item=>Math.hypot(item.fine.globalX-winner.fine.globalX,item.fine.globalY-winner.fine.globalY)>=Math.max(80,winner.fine.radius*.30)),beamMargin=second?winner.combined-second.combined:winner.combined,fine={...winner.fine,localMargin:winner.fine.margin,beamMargin,verifyScore:winner.verify.score,topologyScore:winner.verify.topology,combinedScore:winner.combined,margin:Math.min(winner.fine.margin,beamMargin)},coarse={...winner.hypothesis,margin:coarseSearch.margin,atlas:coarseSearch.atlas,beamResolved:true};return{coarse,fine,alternatives:finals.map(item=>({x:item.fine.globalX,y:item.fine.globalY,angle:item.fine.angle,structuralScore:item.fine.score,denseScore:item.fine.denseScore,contourScore:item.fine.contourScore,phaseScore:item.fine.phaseScore,verifyScore:item.verify.score,combinedScore:item.combined}))}}'''
text, n = re.subn(r'^async function globalMatch\(info,cfg\)\{.*$', global_match, text, count=1, flags=re.M)
assert n == 1, 'globalMatch replacement failed'

gate = r'''function matchGate(coarse,fine,info,cfg){if(!cfg.geometryOk)return`geometry-residual p95=${cfg.p95.toFixed(6)}`;if(info.positiveCount<28)return`insufficient-structural-features ${info.positiveCount}`;if(info.contrast<.12)return`low-normalized-contrast ${info.contrast.toFixed(3)}`;if(!coarse)return'no-coarse-match';if(coarse.score<.30)return`coarse-structure ${coarse.score.toFixed(3)}`;if(!fine)return'no-fine-match';if(fine.score<.36)return`fine-structure ${fine.score.toFixed(3)}`;if(Number.isFinite(fine.contourScore)&&fine.contourScore<.43)return`contour-overlap ${fine.contourScore.toFixed(3)}`;if(Number.isFinite(fine.phaseScore)&&fine.phaseScore<.53)return`structural-phase ${fine.phaseScore.toFixed(3)}`;if(Number.isFinite(fine.verifyScore)&&fine.verifyScore<.43)return`verify-structure ${fine.verifyScore.toFixed(3)}`;if(Number.isFinite(fine.beamMargin)&&fine.beamMargin<.007)return`global-ambiguous ${fine.beamMargin.toFixed(3)}`;return''}'''
text, n = re.subn(r'^function matchGate\(coarse,fine,info,cfg\)\{.*$', gate, text, count=1, flags=re.M)
assert n == 1, 'matchGate replacement failed'

register = r'''async function registerFrame(cfg,mapId){const roiCanvas=VISION.captureRoi(192);if(!roiCanvas)return{reason:'capture-frame-unavailable'};const info=roiSamples(roiCanvas);let coarse=null,fine=null;if(state.mode==='local'&&state.last){fine=await localFineMatch(info,cfg,state.last,160);if(fine){const verify=verifyAt(fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle,info.verifySamples);fine={...fine,verifyScore:verify.score,topologyScore:verify.topology,beamMargin:fine.margin};coarse={score:state.coarseScore,margin:state.coarseMargin,beamResolved:true}}}else if(state.mode==='confirm'&&state.pending?.match){fine=await localFineMatch(info,cfg,state.pending.match,140);if(fine){const verify=verifyAt(fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle,info.verifySamples);fine={...fine,verifyScore:verify.score,topologyScore:verify.topology,beamMargin:fine.margin};coarse={score:state.pending.coarseScore,margin:state.pending.coarseMargin,beamResolved:true}}}else{state.globalSearches++;const global=await globalMatch(info,cfg);coarse=global.coarse;fine=global.fine}if(coarse){state.coarseScore=coarse.score;state.coarseMargin=coarse.margin||0}if(fine){state.fineScore=fine.score;state.fineMargin=fine.margin||0;state.verifyScore=fine.verifyScore||0;state.topologyScore=fine.topologyScore||0;state.denseScore=fine.denseScore||0;state.contourScore=fine.contourScore||0;state.phaseScore=fine.phaseScore||0;state.angle=fine.angle;state.radius=fine.radius}const reason=matchGate(coarse,fine,info,cfg);if(reason)return{reason,coarse,fine,info};const target=pixelToGlobal(fine.globalX,fine.globalY,FINE_Z,cfg);if(!target||!inGlobalBounds(target))return{reason:'target-out-of-global-bounds',coarse,fine,info};return{reason:'',coarse,fine,info,target,mapId}}'''
text, n = re.subn(r'^async function registerFrame\(cfg,mapId\)\{.*$', register, text, count=1, flags=re.M)
assert n == 1, 'registerFrame replacement failed'

text = text.replace("state.verifyScore=0;state.denseScore=0;state.firstSearchAt=0", "state.verifyScore=0;state.denseScore=0;state.contourScore=0;state.phaseScore=0;state.firstSearchAt=0")
text = text.replace("verifyScore:state.verifyScore,denseScore:state.denseScore,topologyScore:state.topologyScore", "verifyScore:state.verifyScore,denseScore:state.denseScore,contourScore:state.contourScore,phaseScore:state.phaseScore,topologyScore:state.topologyScore")
text = text.replace("score:fine?.score??-1,denseScore:fine?.denseScore??-1,verifyScore:fine?.verifyScore??-1", "score:fine?.score??-1,denseScore:fine?.denseScore??-1,contourScore:fine?.contourScore??-1,phaseScore:fine?.phaseScore??-1,verifyScore:fine?.verifyScore??-1")
path.write_text(text, 'utf-8')
